// SmartHelmet/Software/src/components/Sidebar.jsx

import { useState } from 'react';
import '../styles/Sidebar.css';

const NAV_ITEMS = [
  {
    label: 'Dashboard',
    icon: (
      <svg className="nav-icon" viewBox="0 0 18 18" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
        <rect x="1" y="1" width="7" height="7" rx="1.5" />
        <rect x="10" y="1" width="7" height="7" rx="1.5" />
        <rect x="1" y="10" width="7" height="7" rx="1.5" />
        <rect x="10" y="10" width="7" height="7" rx="1.5" />
      </svg>
    ),
  },
  {
    label: 'Alerts',
    icon: (
      <svg className="nav-icon" viewBox="0 0 18 18" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
        <path d="M7 15a2 2 0 0 0 4 0" />
        <path d="M13.73 11c.2-.65.27-1.45.27-2a5 5 0 0 0-10 0c0 .55.07 1.35.27 2l.73 2h8l.73-2Z" />
      </svg>
    ),
  },
  {
    label: 'Tunnel Map',
    icon: (
      <svg className="nav-icon" viewBox="0 0 18 18" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
        <path d="M9 1C6.24 1 4 3.24 4 6c0 4.5 5 11 5 11s5-6.5 5-11c0-2.76-2.24-5-5-5Z" />
        <circle cx="9" cy="6" r="2" />
      </svg>
    ),
  },
  {
    label: 'Settings',
    icon: (
      <svg className="nav-icon" viewBox="0 0 18 18" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
        <circle cx="9" cy="9" r="3" />
        <path d="M15.4 11a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 1 1-2.83 2.83l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V17a2 2 0 0 1-4 0v-.09a1.65 1.65 0 0 0-1.08-1.51 1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 1 1-2.83-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H1a2 2 0 0 1 0-4h.09A1.65 1.65 0 0 0 2.6 6.08a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 1 1 2.83-2.83l.06.06a1.65 1.65 0 0 0 1.82.33H7a1.65 1.65 0 0 0 1-1.51V1a2 2 0 0 1 4 0v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 1 1 2.83 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V7a1.65 1.65 0 0 0 1.51 1H17a2 2 0 0 1 0 4h-.09a1.65 1.65 0 0 0-1.51 1Z" />
      </svg>
    ),
  },
];

export default function Sidebar() {
  const [activeItem, setActiveItem] = useState('Dashboard');

  return (
    <aside className="sidebar-container">
      {/* ── Logo ──────────────────────────────────── */}
      <div className="sidebar-logo">LifeLink</div>

      {/* ── Navigation ────────────────────────────── */}
      <ul className="sidebar-nav">
        {NAV_ITEMS.map(({ label, icon }) => (
          <li
            key={label}
            className={`nav-item${activeItem === label ? ' active' : ''}`}
            onClick={() => setActiveItem(label)}
          >
            {icon}
            <span>{label}</span>
          </li>
        ))}
      </ul>

      {/* ── Worker status chip (pushed to bottom) ── */}
      <div className="worker-chip">
        <span className="worker-chip-dot" />
        <span>Worker</span>
        <span className="ml-auto font-semibold tracking-wide">W001</span>
      </div>
    </aside>
  );
}
